#!/usr/bin/env node
/**
 * mwg.mjs — offline knowledge resolver for the modern-web-guidance repository.
 *
 * Zero dependencies, zero network. Reads references/index.json (generated by
 * scripts/build-index.mjs) and resolves natural-language intents (English or
 * Chinese) to guide ids, then prints the guide so the agent can read it.
 *
 * Commands:
 *   search "<query>"      rank guides for an intent (default 6 results)
 *   retrieve <id,...>     print the full guide(s) / reference(s)
 *   list [category]       list guide ids
 *   cats                  list categories with counts
 *   map [category]        compact one-line-per-guide routing table
 *   stats                 index statistics + staleness hint
 *   check                 validate the index against the repository
 *   features "<query>"    search the 250-feature catalog in the README
 *   glossary [term]       show the Chinese→English query glossary
 *   refs [group]          list Chrome extension references
 *   routes [category]     print the generated intent-routes.md
 *
 * Global options: --json --limit N --category <id> --discipline --root <repo>
 * Env: MWG_ROOT (repository root override)
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const SKILL_DIR = path.resolve(SCRIPT_DIR, '..');
const REF_DIR = path.join(SKILL_DIR, 'references');
const INDEX_FILE = path.join(REF_DIR, 'index.json');

const argv = process.argv.slice(2);
const command = argv[0] || 'help';
const options = { json: false, limit: 6, category: null, discipline: false, root: null, pathOnly: false, head: 0, all: false, two: false, paths: false, maxChars: 0 };
const positional = [];
for (let i = 0; i < argv.length; i += 1) {
  if (i === 0) continue; // argv[0] is the command
  const arg = argv[i];
  if (arg === '--json') options.json = true;
  else if (arg === '--limit') options.limit = Number(argv[++i]) || 6;
  else if (arg === '--category') options.category = String(argv[++i] || '').toLowerCase();
  else if (arg === '--discipline') options.discipline = true;
  else if (arg === '--root') options.root = argv[++i];
  else if (arg === '--path') options.pathOnly = true;
  else if (arg === '--head') options.head = Number(argv[++i]) || 0;
  else if (arg === '--all') options.all = true;
  else if (arg === '--two') options.two = true;
  else if (arg === '--paths') options.paths = true;
  else if (arg === '--max-chars') options.maxChars = Number(argv[++i]) || 0;
  else if (!arg.startsWith('--')) positional.push(arg);
}

function die(message, code = 1) {
  console.error(`mwg: ${message}`);
  process.exit(code);
}

function loadIndex() {
  if (!fs.existsSync(INDEX_FILE)) {
    die(`index not found at ${INDEX_FILE}. Run: node "${path.join(SCRIPT_DIR, 'build-index.mjs')}"`);
  }
  try {
    return JSON.parse(fs.readFileSync(INDEX_FILE, 'utf8'));
  } catch (error) {
    die(`cannot parse index: ${error.message}`);
  }
}

function resolveRoot(index) {
  const candidates = [options.root, process.env.MWG_ROOT, index?.repo?.root].filter(Boolean);
  for (const candidate of candidates) {
    if (fs.existsSync(path.join(candidate, 'skills', 'modern-web-guidance', 'guides'))) return candidate;
  }
  // Fall back to walking up from this skill directory.
  let dir = SKILL_DIR;
  for (;;) {
    if (fs.existsSync(path.join(dir, 'skills', 'modern-web-guidance', 'guides'))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function lowerTokens(text) {
  return (text || '')
    .toLowerCase()
    .split(/[^a-z0-9\u4e00-\u9fff+#.-]+/)
    .map((t) => t.replace(/^[.-]+|[.-]+$/g, ''))
    .filter(Boolean);
}

function stem(token) {
  if (token.length <= 4) return token;
  if (token.endsWith('ies')) return `${token.slice(0, -3)}y`;
  if (token.endsWith('ing') && token.length > 6) return token.slice(0, -3);
  if (token.endsWith('ed') && token.length > 5) return token.slice(0, -2);
  if (token.endsWith('es') && token.length > 4) return token.slice(0, -2);
  if (token.endsWith('s') && !token.endsWith('ss')) return token.slice(0, -1);
  return token;
}

const CJK = /[\u4e00-\u9fff]/;
const CJK_RUN = /[\u4e00-\u9fff]+/g;

/** Common English morphology variants so "validation" can match "validate". */
function variants(token) {
  const out = new Set([token]);
  const stemmed = stem(token);
  if (stemmed !== token) out.add(stemmed);
  if (token.endsWith('ation')) {
    out.add(token.slice(0, -5));
    out.add(`${token.slice(0, -5)}e`);
    out.add(`${token.slice(0, -3)}e`);
  } else if (token.endsWith('tion') || token.endsWith('sion')) {
    out.add(token.slice(0, -4));
  }
  if (token.endsWith('ing')) {
    out.add(token.slice(0, -3));
    out.add(`${token.slice(0, -3)}e`);
  }
  if (token.endsWith('ed')) {
    out.add(token.slice(0, -2));
    out.add(token.slice(0, -1));
  }
  if (token.endsWith('ly')) out.add(token.slice(0, -2));
  if (token.endsWith('ment')) out.add(token.slice(0, -4));
  return [...out].filter((candidate) => candidate.length >= 3);
}

function expandQuery(raw, glossary) {
  const normalized = raw.toLowerCase().replace(/\s+/g, ' ').trim();
  const base = lowerTokens(normalized).map(stem);
  const expansions = new Map(); // token -> weight
  for (const token of base) {
    expansions.set(token, Math.max(expansions.get(token) || 0, 1));
    for (const variant of variants(token)) {
      if (!expansions.has(variant)) expansions.set(variant, 0.8);
    }
  }
  // Chinese runs: every 2-6 character substring is a candidate signal, so a
  // compound phrase ("扩展消息通信") still matches the curated aliases
  // ("消息通信", "消息传递") without a Chinese word segmenter.
  for (const run of raw.toLowerCase().match(CJK_RUN) || []) {
    for (let size = 2; size <= Math.min(6, run.length); size += 1) {
      for (let start = 0; start + size <= run.length; start += 1) {
        const token = run.slice(start, start + size);
        if (!expansions.has(token)) expansions.set(token, 1);
      }
    }
  }
  const matchedTerms = [];
  for (const [zh, english] of Object.entries(glossary || {})) {
    if (typeof zh !== 'string' || !zh) continue;
    const term = zh.toLowerCase();
    let hit = false;
    if (CJK.test(term)) {
      hit = normalized.includes(term);
    } else {
      // ASCII glossary keys must match on word boundaries ("AI" must not match "container").
      const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      hit = new RegExp(`(^|[^a-z0-9])${escaped}([^a-z0-9]|$)`).test(normalized);
    }
    if (!hit) continue;
    matchedTerms.push(zh);
    for (const part of english) {
      for (const token of lowerTokens(part).map(stem)) {
        expansions.set(token, Math.max(expansions.get(token) || 0, 1.6));
      }
    }
  }
  return { normalized, tokens: [...expansions.entries()], matchedTerms };
}

function countOccurrences(haystack, token) {
  if (!haystack || !token) return 0;
  let count = 0;
  let index = haystack.indexOf(token);
  while (index !== -1 && count < 4) {
    count += 1;
    index = haystack.indexOf(token, index + token.length);
  }
  return count;
}

function scoreGuide(guide, query) {
  const { normalized, tokens, matchedTerms } = query;
  const id = guide.id.toLowerCase();
  const idParts = id.split('-').map(stem);
  const title = (guide.title || '').toLowerCase();
  const description = (guide.description || '').toLowerCase();
  const aliasesEn = (guide.aliases?.en || []).join(' ').toLowerCase();
  const aliasesZh = (guide.aliases?.zh || []).join(' ').toLowerCase();
  const headingsText = (guide.headings || []).join(' ').toLowerCase();
  const body = (guide.text || '').toLowerCase();
  const category = (guide.category || '').toLowerCase();

  let score = 0;
  const matched = new Set();
  for (const [token, weight] of tokens) {
    let tokenScore = 0;
    if (idParts.includes(token)) tokenScore += 12;
    if (id === token) tokenScore += 14;
    if (title.includes(token)) tokenScore += 8 * (1 + 0.25 * Math.min(2, countOccurrences(title, token) - 1));
    if (aliasesEn.includes(token)) tokenScore += 7;
    if (headingsText.includes(token)) tokenScore += 2.5;
    if (description.includes(token)) tokenScore += 4;
    if (category.includes(token)) tokenScore += 1.5;
    const bodyCount = countOccurrences(body, token);
    if (bodyCount) tokenScore += 1 + 0.4 * Math.min(3, bodyCount - 1);
    if (tokenScore > 0) {
      matched.add(token);
      score += tokenScore * weight;
    }
  }

  // The whole guide id is covered by the query tokens: strong precision signal.
  const tokenSet = new Set(tokens.map(([token]) => token));
  if (idParts.length && idParts.every((part) => tokenSet.has(part))) score += 12 + Math.min(6, idParts.length);
  // Exact phrase bonuses.
  if (normalized.length >= 4) {
    if (title.includes(normalized)) score += 14;
    if (aliasesEn.includes(normalized)) score += 12;
    if (aliasesZh.includes(normalized) && CJK.test(normalized)) score += 22;
    if (id.includes(normalized.replace(/\s+/g, '-'))) score += 10;
    if (description.includes(normalized)) score += 5;
  }
  // Curated trigger containment. An exact alias equals a strong intent match;
  // a query that contains a curated trigger still gets the bonus.
  for (const zh of guide.aliases?.zh || []) {
    const trigger = zh.toLowerCase();
    if (!trigger) continue;
    if (normalized === trigger) score += 34;
    else if (normalized.includes(trigger)) score += 18;
  }
  for (const en of guide.aliases?.en || []) {
    const trigger = en.toLowerCase();
    if (!trigger) continue;
    if (normalized === trigger) score += 26;
    else if (normalized.includes(trigger)) score += 12;
  }
  for (const term of matchedTerms) {
    if (aliasesZh.includes(term) || title.includes(term)) score += 6;
  }
  // Multiple-signal agreement bonus.
  if (matched.size > 1) score *= 1 + 0.18 * (matched.size - 1);
  // Discipline guides are cross-cutting: small nudge when the category matches.
  if (guide.discipline && normalized.includes(guide.category)) score += 2;
  return score > 0 ? { score, matched: [...matched] } : { score: 0, matched: [] };
}

function searchGuides(index, rawQuery) {
  const query = expandQuery(rawQuery, index.glossary);
  const pool = [];
  for (const guide of index.guides) pool.push({ item: guide, kind: 'guide', scoreData: scoreGuide(guide, query) });
  for (const asset of index.chrome) {
    pool.push({ item: { ...asset, category: 'chrome-extensions' }, kind: 'chrome', scoreData: scoreGuide({ ...asset, category: 'chrome-extensions' }, query) });
  }
  let ranked = pool
    .filter((entry) => entry.scoreData.score > 0.5)
    .filter((entry) => !options.category || entry.item.category === options.category || (options.category === 'chrome-extensions' && entry.kind === 'chrome'))
    .filter((entry) => !options.discipline || (entry.kind === 'guide' && entry.item.discipline))
    .sort((a, b) => b.scoreData.score - a.scoreData.score);
  if (!options.all) ranked = ranked.slice(0, options.limit);
  return { query: rawQuery, expanded: query.tokens.map(([token, weight]) => (weight === 1 ? token : `${token}*${weight}`)), matchedTerms: query.matchedTerms, results: ranked };
}

function formatResult(result) {
  return {
    id: result.item.id,
    kind: result.kind,
    category: result.kind === 'chrome' ? `chrome-extensions/${result.item.group}` : result.item.category,
    title: result.item.title,
    description: result.item.description,
    path: result.item.path,
    score: Math.round(result.scoreData.score * 10) / 10,
    matched: result.scoreData.matched.slice(0, 8),
  };
}

function printSearch(searchResult) {
  const shown = searchResult.results.map(formatResult);
  if (!shown.length) {
    console.log(`no match for "${searchResult.query}".`);
    console.log('Try a concrete UI noun (dialog, table, tooltip, date picker), or use `list` / `map` to browse.');
    if (searchResult.matchedTerms.length) console.log(`glossary terms used: ${searchResult.matchedTerms.join(', ')}`);
    return;
  }
  if (options.json) {
    console.log(JSON.stringify({ ...searchResult, results: shown }, null, 2));
    return;
  }
  if (searchResult.matchedTerms.length) console.log(`glossary: ${searchResult.matchedTerms.slice(0, 4).join(' / ')}`);
  shown.forEach((result, i) => {
    const desc = result.description.length > 110 ? `${result.description.slice(0, 107)}…` : result.description;
    console.log(`${i + 1}. ${result.id}  [${result.category}]  score=${result.score} — ${result.title}`);
    console.log(`   ${desc}`);
    if (options.paths) console.log(`   ${result.path}`);
  });
}

function brief(index, rawQuery) {
  const previousLimit = options.limit;
  options.limit = options.two ? 2 : 1;
  const result = searchGuides(index, rawQuery);
  options.limit = previousLimit;
  if (!result.results.length) {
    printSearch(result);
    return;
  }
  const top = formatResult(result.results[0]);
  const second = result.results[1] ? formatResult(result.results[1]) : null;
  console.log(`# brief: ${rawQuery}`);
  console.log(`route: ${top.id}  [${top.category}]  score=${top.score} — ${top.title}`);
  if (second && second.score >= top.score * 0.75) {
    console.log(`also:  ${second.id}  [${second.category}]  score=${second.score} — ${second.title}`);
  }
  console.log('');
  const ids = [top.id];
  if (options.two && second && second.score >= top.score * 0.75) ids.push(second.id);
  retrieve(index, ids);
}

function findById(index, id) {
  const needle = String(id || '').trim().toLowerCase();
  if (!needle) return null;
  const guide = index.guides.find((g) => g.id.toLowerCase() === needle);
  if (guide) return { ...guide, kind: 'guide' };
  const chrome = index.chrome.find((a) => a.id.toLowerCase() === needle);
  if (chrome) return { ...chrome, kind: 'chrome', category: 'chrome-extensions' };
  return null;
}

function retrieve(index, ids) {
  const root = resolveRoot(index);
  const targets = ids
    .flatMap((id) => String(id).split(','))
    .map((id) => id.trim())
    .filter(Boolean);
  if (!targets.length) die('retrieve needs one or more guide ids, e.g. `retrieve "dialog"` or `retrieve "dialog,tabs"`');
  let missing = 0;
  for (const target of targets) {
    const entry = findById(index, target);
    if (!entry) {
      console.error(`mwg: unknown id "${target}". Run \`search "<intent>"\` first.`);
      missing += 1;
      continue;
    }
    if (options.pathOnly) {
      console.log(root ? path.join(root, entry.path) : entry.path);
      continue;
    }
    if (!root) {
      console.error(`mwg: guide text unavailable (repo root not found); path is ${entry.path}`);
      console.error(`fallback: npx -y modern-web-guidance@latest retrieve "${entry.id}"`);
      missing += 1;
      continue;
    }
    const file = path.join(root, entry.path);
    if (!fs.existsSync(file)) {
      console.error(`mwg: missing file ${file} — run \`node scripts/build-index.mjs\` to refresh the index.`);
      missing += 1;
      continue;
    }
    const raw = fs.readFileSync(file, 'utf8');
    const lines = options.head > 0 ? raw.split(/\r?\n/).slice(0, options.head).join('\n') : raw;
    console.log(`===== ${entry.id} · ${entry.path} (${entry.kind === 'chrome' ? 'chrome-extensions' : entry.category}) =====`);
    console.log(lines);
    console.log(`===== end ${entry.id} =====`);
  }
  if (missing) process.exitCode = 1;
}

function listGuides(index) {
  const category = options.category || (positional[0] ? String(positional[0]).toLowerCase() : null);
  const rows = index.categories
    .filter((c) => !category || c.id === category)
    .map((c) => ({ category: c.id, label: c.label, ids: c.guides }));
  if (options.json) {
    console.log(JSON.stringify(rows, null, 2));
    return;
  }
  for (const row of rows) console.log(`${row.category} (${row.label}): ${row.ids.join(', ')}`);
  if (!category) console.log(`\nchrome-extensions: ${index.chrome.map((a) => a.id).join(', ')}`);
}

function printCats(index) {
  const lines = index.categories.map((c) => `  ${c.id.padEnd(16)} ${String(c.count).padStart(3)}  ${c.label}`);
  console.log(`# categories (${index.counts.categories})`);
  console.log(lines.join('\n'));
  console.log(`  ${'chrome-extensions'.padEnd(16)} ${String(index.counts.chromeAssets).padStart(3)}  Chrome 扩展（独立技能包）`);
  console.log(`\n# discipline guides (${index.counts.disciplines}): ${index.guides.filter((g) => g.discipline).map((g) => g.id).join(', ')}`);
}

function printMap(index) {
  const category = options.category || (positional[0] ? String(positional[0]).toLowerCase() : null);
  const guides = index.guides.filter((g) => !category || g.category === category);
  for (const guide of guides) {
    const zh = (guide.aliases?.zh || []).slice(0, 4).join('、');
    console.log(`${guide.discipline ? '*' : ' '} ${guide.id.padEnd(46)} ${guide.title.slice(0, 28).padEnd(28)} ${zh}`);
  }
  if (!category || category === 'chrome-extensions') {
    console.log('\n# chrome-extensions');
    for (const asset of index.chrome) console.log(`  ${asset.id.padEnd(30)} ${asset.group.padEnd(10)} ${asset.title}`);
  }
  console.log('\n(* = discipline / cross-cutting guide)');
}

function newestMtime(dir) {
  let newest = 0;
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop();
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) stack.push(full);
      else if (entry.isFile()) newest = Math.max(newest, fs.statSync(full).mtimeMs);
    }
  }
  return newest;
}

function printStats(index) {
  const root = resolveRoot(index);
  console.log(`index: ${INDEX_FILE}`);
  console.log(`generated: ${index.generatedAt}`);
  console.log(`repo: ${root || index.repo.root}  version=${index.repo.version}  skill-version=${index.repo.skillVersion}`);
  console.log(`guides: ${index.counts.guides}  use-cases: ${index.counts.useCases}  discipline: ${index.counts.disciplines}  categories: ${index.counts.categories}`);
  console.log(`chrome: ${index.counts.chromeAssets} assets  features: ${index.counts.features}  glossary: ${index.counts.glossaryTerms} terms  aliased: ${index.counts.aliasedGuides} guides`);
  if (root) {
    const indexTime = fs.statSync(INDEX_FILE).mtimeMs;
    const guideTime = newestMtime(path.join(root, 'skills', 'modern-web-guidance', 'guides'));
    const readmeTime = fs.statSync(path.join(root, 'README.md')).mtimeMs;
    const stale = Math.max(guideTime, readmeTime) > indexTime + 1000;
    console.log(`freshness: ${stale ? 'STALE — run build-index.mjs' : 'fresh'}`);
  }
}

function check(index) {
  const root = resolveRoot(index);
  const problems = [];
  if (!root) problems.push('repository root not found (set MWG_ROOT)');
  else {
    for (const entry of [...index.guides, ...index.chrome]) {
      const file = path.join(root, entry.path);
      if (!fs.existsSync(file)) problems.push(`missing file for ${entry.id}: ${entry.path}`);
    }
    const guideDir = path.join(root, 'skills', 'modern-web-guidance', 'guides');
    let files = 0;
    const stack = [guideDir];
    while (stack.length) {
      const current = stack.pop();
      for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
        const full = path.join(current, entry.name);
        if (entry.isDirectory()) stack.push(full);
        else if (entry.isFile() && entry.name.endsWith('.md')) files += 1;
      }
    }
    if (files !== index.counts.guides) problems.push(`guide count mismatch: filesystem=${files} index=${index.counts.guides} (rebuild)`);
    const readme = fs.readFileSync(path.join(root, 'README.md'), 'utf8');
    const useCases = (readme.match(/^- \*\*\[[^\]]+\]\([^)]+\)\*\*:/gm) || []).length;
    if (useCases !== index.counts.useCases) problems.push(`README use-case count changed: README=${useCases} index=${index.counts.useCases} (rebuild)`);
  }
  if (problems.length) {
    console.error(`mwg check: ${problems.length} problem(s)`);
    problems.slice(0, 20).forEach((p) => console.error(`  - ${p}`));
    process.exitCode = 1;
  } else {
    console.log(`mwg check: OK — ${index.counts.guides} guides, ${index.counts.chromeAssets} chrome assets, ${index.counts.features} features all resolve.`);
  }
}

function searchFeatures(index, query) {
  const tokens = lowerTokens(query).map(stem);
  const needle = String(query).toLowerCase();
  const hits = index.features
    .filter((feature) => {
      const name = feature.name.toLowerCase();
      return name.includes(needle) || tokens.some((token) => name.includes(token));
    })
    .slice(0, options.all ? 200 : Math.max(options.limit, 12));
  if (options.json) {
    console.log(JSON.stringify(hits, null, 2));
    return;
  }
  if (!hits.length) {
    console.log(`no feature named like "${query}" in the 250-feature catalog.`);
    return;
  }
  for (const hit of hits) console.log(`- ${hit.name}  [${hit.group}]  ${hit.url}`);
}

function printGlossary(index, filter) {
  const term = (filter || '').toLowerCase();
  const entries = Object.entries(index.glossary).filter(([zh, en]) => !term || zh.toLowerCase().includes(term) || en.join(' ').toLowerCase().includes(term));
  for (const [zh, en] of entries) console.log(`${zh} → ${en.join(', ')}`);
}

function printRefs(index, group) {
  const rows = index.chrome.filter((asset) => !group || asset.group === group);
  for (const asset of rows) console.log(`${asset.id.padEnd(28)} ${asset.group.padEnd(10)} ${asset.title}`);
}

function printRoutes() {
  const file = path.join(REF_DIR, 'intent-routes.md');
  if (!fs.existsSync(file)) die('intent-routes.md not generated yet; run build-index.mjs');
  console.log(fs.readFileSync(file, 'utf8'));
}

function help() {
  console.log(`mwg — offline modern-web-guidance resolver (zero network)

usage:
  node scripts/mwg.mjs search "<intent in English or Chinese>" [--limit 6] [--json] [--category css] [--discipline] [--paths]
  node scripts/mwg.mjs brief "<intent>" [--two] [--head 120]
  node scripts/mwg.mjs retrieve "<id>[,<id>...]" [--path] [--head 120]
  node scripts/mwg.mjs list [category]
  node scripts/mwg.mjs cats | map [category] | stats | check
  node scripts/mwg.mjs features "<feature name>"
  node scripts/mwg.mjs glossary [term]
  node scripts/mwg.mjs refs [group]
  node scripts/mwg.mjs routes

tips:
  - brief = search + read the top guide in ONE process (recommended for the locate step)
  - query with a 2-5 word action + concrete UI noun ("light dismiss dialog", "responsive table", "dark mode scrollbar")
  - split compound tasks into separate searches
  - set MWG_ROOT when the repository moved, then run build-index.mjs`);
}

const index = loadIndex();
switch (command) {
  case 'search': {
    const query = positional[0] || '';
    if (!query) die('search needs a query, e.g. `search "light dismiss dialog"`');
    printSearch(searchGuides(index, query));
    break;
  }
  case 'brief':
    brief(index, positional[0] || '');
    break;
  case 'retrieve':
    retrieve(index, positional);
    break;
  case 'list':
    listGuides(index);
    break;
  case 'cats':
  case 'categories':
    printCats(index);
    break;
  case 'map':
    printMap(index);
    break;
  case 'stats':
    printStats(index);
    break;
  case 'check':
    check(index);
    break;
  case 'features':
    searchFeatures(index, positional[0] || '');
    break;
  case 'glossary':
    printGlossary(index, positional[0]);
    break;
  case 'refs':
    printRefs(index, positional[0]);
    break;
  case 'routes':
    printRoutes();
    break;
  case 'help':
  case '--help':
  case '-h':
  default:
    help();
    break;
}
